SELECT CAST('board' AS TEXT) AS kind, board_id AS record_id, workspace_id AS workspace_id, board_id AS board_id, name AS business_name, payload AS payload, router_time AS router_time, time_basis AS time_basis, origin_installation AS origin_installation, origin_machine AS origin_machine, import_digest AS import_digest FROM boards WHERE workspace_id = ? ORDER BY board_id;
